<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Domain\Marketing\MarketingPermission;
use App\Services\Marketing\MarketingPosts;
use Illuminate\Http\Request;
class MarketingPostsController extends Controller {
 private function access(Request $r,bool $edit=false):int{abort_unless(MarketingPermission::allows($r->user(),$edit?MarketingPermission::EDIT:MarketingPermission::VIEW),403);return $r->user()->id;}
 private function boot(Request $r,MarketingPosts $s):array{$id=$this->access($r);$posts=$s->listing($id);$assets=$s->library($id)['assets'];foreach($posts as $p)if($p['asset']??null){$a=$s->asset($id,$p['asset']);if($a&&!collect($assets)->contains('id',$a['id']))$assets[]=$a;}return ['posts'=>$posts,'accounts'=>$s->accounts(),'assets'=>$assets,'publishingEnabled'=>(bool)config('marketing.social_publishing_enabled',false)&&$r->user()->is_super_admin,'canEdit'=>MarketingPermission::allows($r->user(),MarketingPermission::EDIT),'csrf'=>csrf_token(),'base'=>url('/admin/marketing/posts/data'),'page'=>$r->routeIs('marketing.preview.calendar')?'calendar':'posts','urls'=>MarketingNavigationController::boot('posts')['urls']];}
 public function index(Request $r,MarketingPosts $s){return response()->view('marketing.posts.index',['boot'=>$this->boot($r,$s)])->header('Cache-Control','private, no-store');}
 public function data(Request $r,MarketingPosts $s){return response()->json($this->boot($r,$s))->header('Cache-Control','private, no-store');}
 public function library(Request $r,MarketingPosts $s){$id=$this->access($r);$d=$r->validate(['q'=>'nullable|string|max:100','page'=>'nullable|integer|min:1|max:10000']);return response()->json($s->library($id,$d['q']??'',(int)($d['page']??1)))->header('Cache-Control','private, no-store');}
 public function write(Request $r,string $action,MarketingPosts $s){$id=$this->access($r,true);$rules=['id'=>'required|uuid','version'=>'required|integer|min:0'];if(!in_array($action,['cancel','refresh'],true))$rules+=['title'=>'nullable|string|max:255','copy'=>'nullable|string|max:10000','targets'=>'present|array|max:30','targets.*'=>'required|uuid|distinct','copies'=>'present|array|max:30','copies.*'=>'nullable|string|max:10000','asset'=>'nullable|string|max:100','type'=>'required|in:Post,Reel','tz'=>'required|timezone','due'=>'nullable|date'];$d=$r->validate($rules);if(in_array($action,['publish','refresh'],true)){abort_unless($r->user()->is_super_admin,403);$publisher=app(\App\Services\Marketing\MarketingImagePublisher::class);$post=$action==='publish'?$publisher->start($id,$d):$publisher->refresh($id,$d['id']);}else $post=$s->write($id,$action,$d);return response()->json(['post'=>$post])->header('Cache-Control','private, no-store');}
 public function delivery(int $attempt){return app(\App\Services\Marketing\MarketingImagePublisher::class)->delivery($attempt);}
 public function media(Request $r,string $asset,MarketingPosts $s){$id=$this->access($r);abort_unless($s->asset($id,$asset),404);if(str_starts_with($asset,'image:')){$row=\App\Models\ProductImage::findOrFail(substr($asset,6));return response()->file($s->imagePath($row->path),['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}[$kind,$run,$format]=explode(':',$asset);$row=\App\Models\MarketingTemplateRun::findOrFail($run)->result['formats'][$format];return response()->file(app(\App\Services\Marketing\MarketingVideoFiles::class)->file($row['path'],$row['sha256']),['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
